let data=null,session=null,clubId='',page='dashboard',demo=false,previewId=null,search='',filter='all',draft=null,draftDay=0,selectedDay=(new Date(dayOffset(0)+'T12:00:00').getDay()+1)%7,weekOffset=0,interval=null,deadline=0,remaining=60,restAlerts=null,installPrompt=null;
const find=id=>exercises.find(e=>e.id===id),members=()=>data.members.filter(m=>m.role==='member'&&m.status!=='archived'),manager=()=>data&&['owner','trainer'].includes(data.me.role)&&!previewId,isOwner=()=>data?.me.role==='owner',myMember=()=>previewId?data.members.find(m=>m.id===previewId):data.me;
const money=n=>Number(n||0).toLocaleString('en-US'),date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('ar-IQ',{day:'numeric',month:'short'}):'—',initials=n=>n.split(' ').map(w=>w[0]).slice(0,2).join(''),daysLeft=m=>Math.ceil((new Date(m.endDate+'T12:00:00')-new Date(dayOffset(0)+'T12:00:00'))/86400000),status=m=>m.status==='archived'?'archived':m.status==='paused'?'paused':daysLeft(m)<0?'expired':'active';
