function toast(text,error=false){$('#toast').textContent=text;$('#toast').hidden=false;$('#toast').classList.toggle('error',error);clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').hidden=true,4200)}
async function api(route,body){$('#liveState').textContent=body?'قيد الحفظ…':'تحديث…';try{const response=await fetch('/api/'+route+(body?'':route==='club'?'?club='+encodeURIComponent(clubId):''),{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify({...body,...(clubId?{clubId}:{})}):undefined,credentials:'same-origin',cache:'no-store'});const value=await response.json();if(!response.ok){if(response.status===401&&!['login','register'].includes(route)){if(!demo)loginGate();throw Error('انتهت الجلسة. سجّل الدخول مجدداً.')}throw Error(value.error||'تعذّر إكمال العملية')}$('#liveState').textContent='متصل';return value}catch(e){$('#liveState').textContent='تعذّر الاتصال';throw e}}
async function refresh(){data=await api('club');renderShell();render()}
async function mutate(route,body,message){await api(route,body);await refresh();if(message)toast(message)}
function modal(html){$('#modalBody').innerHTML=html;hydrate();if(!$('#modal').open)$('#modal').showModal();mountClips()}
