function authGate(register=false){$('#gate').hidden=false;$('#shell').hidden=true;$('#gateContent').innerHTML=`<span class="overline">${register?'CREATE YOUR CLUB':'YOUR CLUB. YOUR SPACE.'}</span><h1>${register?'أطلق مساحة ناديك.':'تمرّن بخطّة.<br><em>وتقدّم بثقة.</em>'}</h1><p>${register?'أنشئ حساب الإدارة، ثم أضف المشتركين وحدد لكل واحد برنامجه.':'الكوتش يجهّز برنامجك. وأنت تركز على تمرينك.<br>ادخل باسم المستخدم وكلمة المرور اللذين أعطاك إياهما النادي.'}</p><form id="authForm" data-register="${register}">${register?'<label class="field">اسمك الكامل<input name="name" required maxlength="60" autocomplete="name" placeholder="اسم مدير النادي"></label>':''}<label class="field">اسم المستخدم<input name="username" required minlength="3" maxlength="40" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="مثال: omar.club"></label><label class="field">كلمة المرور<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="${register?'new-password':'current-password'}" placeholder="١٠ أحرف على الأقل"></label>${register?'<label class="field">اسم النادي<input name="clubName" required minlength="3" maxlength="60" placeholder="اسم ناديك الرياضي"></label><label class="field">المدينة<input name="city" maxlength="50" placeholder="أربيل"></label>':''}<p id="authError" class="danger" role="alert" style="margin:0 0 12px"></p><button class="primary" type="submit" style="width:100%">${register?'إنشاء حساب النادي':'تسجيل الدخول'} ${icon('arrow')}</button></form><div class="actions" style="margin-top:16px"><button class="ghost" id="switchAuth">${register?'لدي حساب بالفعل':'أنت الكوتش؟ أنشئ مساحتك'}</button></div><div class="notice">للمشترك: إذا نسيت كلمة المرور، اطلب من إدارة ناديك إعادة تعيينها. لكل مشترك حساب خاص بالنادي وبرنامج يحدده الكوتش.</div>`;hydrate();$('#switchAuth').onclick=()=>loginGate(!register);$('#authForm').onsubmit=async e=>{e.preventDefault();const f=e.target,button=f.querySelector('[type=submit]');button.disabled=true;$('#authError').textContent='';try{const b=Object.fromEntries(new FormData(f));await api(register?'register':'login',b);if(register){const c=await api('clubs',{name:b.clubName,city:b.city});clubId=c.clubId}await boot()}catch(error){if($('#authError'))$('#authError').textContent=error.message}finally{button.disabled=false}};}

let pendingLevel=null,planLevelFilter='all',onboardingBusy=false;
