function levelCards(selected=null){return `<div class="level-options"><button class="level-choice starter ${selected==='beginner'?'selected':''}" data-entry-level="beginner" aria-pressed="${selected==='beginner'}"><span class="level-top"><span class="level-symbol">${icon('bolt')}</span><span class="selection-dot">${selected==='beginner'?icon('check'):''}</span></span><small>START STRONG / 01</small><h2>أنا مبتدئ.</h2><p>أبني الأساس، أفهم الحركة، وأتقدّم خطوة بخطوة.</p><span class="level-tag">بداية بثقة ${icon('arrow')}</span></button><button class="level-choice pro ${selected==='advanced'?'selected':''}" data-entry-level="advanced" aria-pressed="${selected==='advanced'}"><span class="level-top"><span class="level-symbol">${icon('dumbbell')}</span><span class="selection-dot">${selected==='advanced'?icon('check'):''}</span></span><small>RAISE THE BAR / 02</small><h2>أنا محترف.</h2><p>أتمرّن بخبرة، أتابع أوزاني، وأرفع مستوى أدائي.</p><span class="level-tag">تحدّي جديد ${icon('arrow')}</span></button></div>`}
