function renderSessionSummary(){const d=currentDay(),logs=validDayLogs(d,dayLogs()),total=d.items.reduce((n,r)=>n+r.sets,0),complete=logs.length===total;$('#view').innerHTML=`<section class="session-summary"><span class="summary-seal">${icon(complete?'check':'chart')}</span><span class="micro-label">${complete?'SESSION COMPLETE':'YOUR SESSION SO FAR'}</span><h1>${complete?'أنجزتها.':'كل جولة،'}<br><em>${complete?'وأنت أقوى.':'إلها قيمة.'}</em></h1><p>${esc(d.title)} · ${dayNames[selectedDay]} · أسبوع ${date(weekKey())}</p><div class="summary-numbers"><div><b>${logs.length}<small>/${total}</small></b><span>جولة مسجّلة</span></div><div><b>${new Set(logs.map(l=>l.exerciseId)).size}</b><span>حركات سُجّلت</span></div></div>${d.items.map(r=>{const n=logs.filter(l=>l.exerciseId===r.id).length;return `<div class="summary-exercise"><span>${n===r.sets?icon('check'):icon('clock')}</span><b>${esc(find(r.id).name)}</b><small>${n}/${r.sets}</small></div>`}).join('')}<button class="primary" data-enter-session>${complete?'راجع الجولات':'أكمل الحصّة'} ${icon('arrow')}</button><button class="secondary" data-session-back>العودة للأسبوع</button><p class="summary-saved">أوزانك وتكراراتك محفوظة في حسابك${demo?' التجريبي المؤقت':''}.</p></section>`}
