function paintTimer(){if($('#timerNumber'))$('#timerNumber').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if($('#timerButton'))$('#timerButton').innerHTML=icon(interval?'pause':'play')+(interval?' إيقاف مؤقت':' ابدأ الراحة')}
function tick(){if(!interval)return;remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));if(!remaining){stopTimer();if($('#timerState'))$('#timerState').textContent='انتهت الراحة. جاهز للجولة التالية!';toast('انتهت الراحة. وقت الجولة التالية.');void restAlerts?.notify()}paintTimer()}
