 if(b.dataset.openDay!==undefined){selectedDay=+b.dataset.openDay;sessionMode='week';page='workout';render();window.scrollTo(0,0);return}

 if(b.hasAttribute('data-enter-session')){enterSession();return}
 if(b.hasAttribute('data-session-back')){sessionMode='week';render();window.scrollTo(0,0);return}
