 if(b.dataset.selectSessionDay!==undefined){selectedDay=+b.dataset.selectSessionDay;sessionMode='week';render();return}
 if(b.dataset.sessionWeek){weekOffset+=+b.dataset.sessionWeek;sessionMode='week';render();return}
 if(b.dataset.sessionExercise!==undefined){selectSessionExercise(+b.dataset.sessionExercise);render();return}
 if(b.dataset.sessionRound!==undefined){activeRound=+b.dataset.sessionRound;render();return}
 if(b.hasAttribute('data-next-exercise')){if(exerciseIndex===currentDay().items.length-1)sessionMode='summary';else selectSessionExercise(exerciseIndex+1);render();window.scrollTo(0,0);return}
 if(b.hasAttribute('data-previous-exercise')){selectSessionExercise(exerciseIndex-1);render();window.scrollTo(0,0);return}
 if(b.dataset.stepField){const input=$('#'+b.dataset.stepField),n=+(input.value||0)+(+b.dataset.step);input.value=Math.max(+input.min,Math.min(+input.max,n));input.dispatchEvent(new Event('input',{bubbles:true}));return}
 if(b.hasAttribute('data-copy-last')){const r=currentDay().items[exerciseIndex],records=myLogs(myMember().id).filter(l=>l.exerciseId===r.id&&l.done&&l.week<=weekKey()).sort((a,b)=>b.week.localeCompare(a.week)||b.updatedAt.localeCompare(a.updatedAt)),l=records.find(l=>l.week<weekKey())||records[0];if(l){$('#activeWeight').value=l.weight;$('#activeReps').value=l.reps;$('#activeWeight').dispatchEvent(new Event('input',{bubbles:true}))}return}
 if(b.hasAttribute('data-undo-active-set')){const r=currentDay().items[exerciseIndex],l=dayLogs().find(l=>l.exerciseId===r.id&&l.round===activeRound);if(l){b.disabled=true;await api('log',{week:weekKey(),day:selectedDay,exerciseId:r.id,round:activeRound,weight:l.weight,reps:l.reps,done:false});sessionDrafts.delete(draftKey());data=await api('club');render();toast('تم إلغاء إنجاز الجولة؛ يمكنك تسجيلها مجدداً.')}return}
 if(b.hasAttribute('data-save-active-set')){await saveActiveSet(b);return}
 if(b.hasAttribute('data-rest-add')){remaining+=30;if(interval)deadline=Date.now()+remaining*1000;paintTimer();return}
 if(b.hasAttribute('data-end-rest')){stopTimer();remaining=0;paintTimer();return}

 if(b.dataset.muscle){libraryMuscle=b.dataset.muscle;libraryPage();return}
 if(b.hasAttribute('data-start-today')){enterSession((new Date(dayOffset(0)+'T12:00:00').getDay()+1)%7);return}
 if(b.hasAttribute('data-next-quote')){quoteIndex=(quoteIndex+1)%motivation.length;$('#dailyQuote').textContent=motivation[quoteIndex];return}
 if(b.dataset.page){sessionMode='week';page=b.dataset.page;search='';filter='all';if($('.sidebar').classList.contains('open'))setDrawer(false);if($('#modal').open)closeModal();render();window.scrollTo({top:0,behavior:'instant'});return}
 if(b.hasAttribute('data-close')){closeModal();return}
 if(b.dataset.action){const action=b.dataset.action;if(action==='new-member')memberForm();if(action==='new-trainer')memberForm('trainer');if(action==='new-plan')newPlanChoice();return}
 if(b.dataset.member){memberDetail(b.dataset.member);return}
 if(b.dataset.editMember){memberForm('member',data.members.find(m=>m.id===b.dataset.editMember));return}
 if(b.dataset.reset){passwordDialog(false,b.dataset.reset);return}
 if(b.dataset.editPlan){startBuilder(data.plans.find(p=>p.id===b.dataset.editPlan));return}
