 if(b.dataset.customMember){startBuilder(null,b.dataset.customMember);return}
 if(b.dataset.previewMember){previewId=b.dataset.previewMember;sessionMode='week';page='workout';closeModal();render();window.scrollTo(0,0);return}
 if(b.dataset.motion){movement(b.dataset.motion);return}
